const GB_LOGO    = "data:image/png;base64,"
const WS_LOGO    = "data:image/png;base64,"
const LU_LOGO    = "data:image/png;base64,"
const MM_LOGO    = "data:image/png;base64,"
const SB_LOGO    = "data:image/png;base64,"
const MB_LOGO    = "data:image/png;base64,"

/* Team photos */
const PHOTO_GK      = "data:image/jpeg;base64,"
const PHOTO_NO6     = "data:image/jpeg;base64,"
const PHOTO_NO5     = "data:image/jpeg;base64,"
const PHOTO_DUO1    = "data:image/jpeg;base64,"
const PHOTO_DUO2    = "data:image/jpeg;base64,"
const PHOTO_NO17    = "data:image/jpeg;base64,"

/* ── STORIES DATA ── */
const STORIES = [
  { id:"ws",  logo:WS_LOGO,  opp:"White Staff",       score:"0-1", result:"L", venue:"Away",
    photo:PHOTO_NO6,
    caption:"Tough away day vs The White Machine. We fight on. 💪 #90Stars" },
  { id:"lu",  logo:LU_LOGO,  opp:"Letlhakane Utd",    score:"2-0", result:"W", venue:"Away",
    photo:PHOTO_DUO2,
    caption:"2-0 away win vs Letlhakane United! The boys delivered. 🔥 #HoneyBadgers" },
  { id:"mm",  logo:MM_LOGO,  opp:"Mmatshumo Classic", score:"0-2", result:"L", venue:"Away",
    photo:PHOTO_DUO1,
    caption:"Tough result away at Mmatshumo. We learn and bounce back. 💛 #90Stars" },
  { id:"sb",  logo:SB_LOGO,  opp:"Stone Breakers",    score:"1-0", result:"W", venue:"Away",
    photo:PHOTO_GK,
    caption:"MASSIVE 1-0 WIN vs Stone Breakers! Casemiro with the goal, Lenyatso unbeatable in goal! 🙌 #HoneyBadgers" },
  { id:"mb",  logo:MB_LOGO,  opp:"Mighty Birds",      score:"0-2", result:"L", venue:"Away",
    photo:PHOTO_NO17,
    caption:"Lost 0-2 away to Mighty Birds. Heads up, Golden Birds next! ⚽ #90Stars" },
  { id:"gb",  logo:GB_LOGO,  opp:"Golden Birds",      score:null,  result:null, venue:"HOME",
    photo:PHOTO_NO5,
    caption:"NEXT UP: Golden Birds at Falcon Ground! Home crowd, let's go! 🦡💛 #Week24" },
]

/* ── NEWS DATA ── */
const LOCAL_NEWS = [
  {
    id:"n1", tag:"MATCH", date:"19 May 2026",
    title:"Lenyatso Heroics Seal 1-0 Win vs Stone Breakers",
    body:"Ditsaone \"Casemiro\" Gaeimelwe broke the deadlock with a clinical finish, but the real story was goalkeeper Bosenakitso Lenyatso who produced an exceptional display — saving 3 one-on-one situations to keep the Honey Badgers ahead.",
    photo: PHOTO_GK,
    photoCaption:"Lenyatso (GK) — 3 saves, 1 clean sheet",
  },
  {
    id:"n2", tag:"SQUAD", date:"02 May 2026",
    title:"The Honey Badgers Ready for Battle",
    body:"The squad showed great spirit ahead of the away stretch. Training hard, playing harder. These boys represent the Boteti with pride. 🦡",
    photo: PHOTO_DUO2,
    photoCaption:"Ready for the away games",
  },
  {
    id:"n3", tag:"MATCH", date:"05 May 2026",
    title:"90 Stars Demolish Letlhakane United 2-0 Away",
    body:"A dominant display away from home. The Honey Badgers were clinical, winning 2-0 in Letlhakane to prove their away credentials.",
    photo: PHOTO_DUO1,
    photoCaption:"Celebrating the Letlhakane win",
  },
  {
    id:"n4", tag:"SQUAD", date:"May 2026",
    title:"Goalkeeper Mosweu — Wall Between the Posts",
    body:"The Pink Wall has been a key part of our season. Our keeper's performances have kept us in multiple matches. The number 1 is ready for Golden Birds.",
    photo: PHOTO_GK,
    photoCaption:"Mosweu ready with gloves on",
  },
]

/* ── ROAD DATA ── */
const ROAD_FALLBACK = [
  { opp:"White Staff",       score:"0-1", result:"L", venue:"Away", logo:WS_LOGO },
  { opp:"Letlhakane Utd",    score:"2-0", result:"W", venue:"Away", logo:LU_LOGO },
  { opp:"Mmatshumo Classic", score:"0-2", result:"L", venue:"Away", logo:MM_LOGO },
  { opp:"Stone Breakers",    score:"1-0", result:"W", venue:"Away", logo:SB_LOGO },
  { opp:"Mighty Birds",      score:"0-2", result:"L", venue:"Away", logo:MB_LOGO },
]

/* ════════════════════════════════════════════════════ */

const ForYouScreen = ({ session, openMembership, setActiveTab }) => {
  const [news,        setNews]        = useState([])
  const [fixtures,    setFixtures]    = useState([])
  const [showDonate,  setShowDonate]  = useState(false)
  const [countdown,   setCountdown]   = useState(null)
  const [storyIdx,    setStoryIdx]    = useState(null)  // null = no story open
  const [storyProg,   setStoryProg]   = useState(0)
  const storyTimer = useRef(null)

  useEffect(()=>{
    supabase.from("news").select("*").eq("published",true)
      .order("created_at",{ascending:false}).limit(10)
      .then(({data})=>{ if(data) setNews(data) })
    supabase.from("fixtures").select("*").order("match_date",{ascending:true})
      .then(({data})=>{ if(data) setFixtures(data) })
  },[])

  const nextFixture = { match_date:"2026-05-23", kick_off:"13:30", opponent:"Golden Birds", venue:"HOME" }

  useEffect(()=>{
    const tick = () => {
      try {
        const [yr,mo,dy] = nextFixture.match_date.split("-").map(Number)
        const [hh,mm]    = (nextFixture.kick_off||"13:30").split(":").map(Number)
        const matchTime  = new Date(yr, mo-1, dy, hh, mm, 0)
        const diff       = matchTime - new Date()
        if(diff <= 0){ setCountdown(null); return }
        setCountdown({
          d: Math.floor(diff/86400000),
          h: Math.floor((diff%86400000)/3600000),
          m: Math.floor((diff%3600000)/60000),
          s: Math.floor((diff%60000)/1000),
        })
      } catch(e){ setCountdown(null) }
    }
    tick()
    const id = setInterval(tick, 1000)
    return ()=>clearInterval(id)
  },[])

  /* Story auto-advance */
  const openStory = (idx) => {
    setStoryIdx(idx)
    setStoryProg(0)
    clearInterval(storyTimer.current)
    storyTimer.current = setInterval(()=>{
      setStoryProg(p=>{
        if(p >= 100){
          clearInterval(storyTimer.current)
          setStoryIdx(i => {
            const next = i + 1
            if(next < STORIES.length){
              storyTimer.current = setInterval(()=>{}, 50) // will reset on effect
              setTimeout(()=> openStory(next), 0)
              return null
            }
            return null
          })
          return 100
        }
        return p + 2
      })
    }, 100) // 5 seconds total (100/2 * 100ms)
  }

  const closeStory = () => {
    clearInterval(storyTimer.current)
    setStoryIdx(null)
    setStoryProg(0)
  }

  useEffect(()=> ()=>clearInterval(storyTimer.current), [])

  const Box = ({val,label}) => (
    <div style={{textAlign:"center"}}>
      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
        fontSize:"clamp(22px,6vw,30px)",color:GOLD,lineHeight:1,
        background:"rgba(255,255,255,0.1)",borderRadius:8,padding:"4px 8px",minWidth:44}}>
        {String(val).padStart(2,"0")}
      </div>
      <div style={{fontSize:9,color:"rgba(255,255,255,0.6)",marginTop:3,
        fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
        letterSpacing:"0.08em"}}>{label}</div>
    </div>
  )

  const displayNews = [...LOCAL_NEWS, ...news.map(n=>({
    id:n.id, tag:n.tag||"NEWS", date:new Date(n.created_at).toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"}),
    title:n.title, body:n.summary, photo:PHOTO_DUO1, photoCaption:"",
  }))]

  return (
    <div style={{flex:1,overflowY:"auto",WebkitOverflowScrolling:"touch",background:"#f5f6fa"}}>
      {showDonate&&<DonateModal onClose={()=>setShowDonate(false)} session={session}/>}

      {/* ══ STORY OVERLAY ══ */}
      {storyIdx!==null&&storyIdx<STORIES.length&&(()=>{
        const s = STORIES[storyIdx]
        const win  = s.result==="W"
        const loss = s.result==="L"
        return (
          <div style={{position:"fixed",inset:0,zIndex:1000,background:"#000",
            display:"flex",flexDirection:"column"}}
            onClick={closeStory}>
            {/* Progress bars */}
            <div style={{display:"flex",gap:3,padding:"10px 10px 6px",flexShrink:0}}>
              {STORIES.map((_,i)=>(
                <div key={i} style={{flex:1,height:3,borderRadius:2,
                  background:"rgba(255,255,255,0.3)",overflow:"hidden"}}>
                  <div style={{height:"100%",borderRadius:2,background:WHITE,
                    width: i<storyIdx?"100%":i===storyIdx?`${storyProg}%`:"0%",
                    transition:i===storyIdx?"none":"none"}}/>
                </div>
              ))}
            </div>
            {/* Header */}
            <div style={{display:"flex",alignItems:"center",gap:10,
              padding:"6px 12px 8px",flexShrink:0}}>
              <img src={STARS_LOGO} style={{width:36,height:36,borderRadius:"50%",
                border:"2px solid "+GOLD,objectFit:"contain",background:NAVY,padding:2}}/>
              <div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                  fontSize:14,color:WHITE}}>90 STARS ACADEMY</div>
                <div style={{fontSize:11,color:"rgba(255,255,255,0.6)"}}>
                  vs {s.opp} · {s.venue}
                </div>
              </div>
              <button onClick={closeStory}
                style={{marginLeft:"auto",background:"none",border:"none",
                  color:WHITE,fontSize:22,cursor:"pointer",lineHeight:1}}>✕</button>
            </div>
            {/* Photo */}
            <div style={{flex:1,position:"relative",overflow:"hidden"}}>
              <img src={s.photo} alt={s.opp}
                style={{width:"100%",height:"100%",objectFit:"cover",objectPosition:"center top"}}/>
              {/* Gradient overlays */}
              <div style={{position:"absolute",top:0,left:0,right:0,height:"30%",
                background:"linear-gradient(to bottom,rgba(0,0,0,0.5),transparent)"}}/>
              <div style={{position:"absolute",bottom:0,left:0,right:0,height:"40%",
                background:"linear-gradient(to top,rgba(0,0,0,0.8),transparent)"}}/>
              {/* Score badge */}
              {s.score&&(
                <div style={{position:"absolute",top:16,right:16,
                  background:win?"rgba(245,197,24,0.9)":loss?"rgba(192,57,43,0.9)":"rgba(50,50,50,0.9)",
                  borderRadius:12,padding:"6px 14px",textAlign:"center"}}>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                    fontSize:22,color:win?NAVY:WHITE,lineHeight:1}}>{s.score}</div>
                  <div style={{fontSize:9,color:win?NAVY:WHITE,fontWeight:700}}>
                    {win?"WIN":loss?"LOSS":"DRAW"}
                  </div>
                </div>
              )}
              {!s.score&&(
                <div style={{position:"absolute",top:16,right:16,
                  background:"rgba(245,197,24,0.9)",borderRadius:12,padding:"6px 14px"}}>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                    fontSize:14,color:NAVY}}>NEXT UP ⚽</div>
                </div>
              )}
              {/* Opponent logo */}
              <div style={{position:"absolute",top:16,left:60,
                width:44,height:44,borderRadius:"50%",
                background:"rgba(255,255,255,0.15)",
                display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden"}}>
                <img src={s.logo} style={{width:"85%",height:"85%",objectFit:"contain"}}/>
              </div>
              {/* Caption */}
              <div style={{position:"absolute",bottom:0,left:0,right:0,padding:"16px 14px"}}>
                <div style={{fontSize:"clamp(13px,4vw,16px)",color:WHITE,lineHeight:1.5,
                  fontWeight:600,textShadow:"0 1px 6px rgba(0,0,0,0.8)"}}>
                  {s.caption}
                </div>
              </div>
            </div>
            {/* Nav arrows */}
            <div style={{display:"flex",padding:"12px 14px",gap:10,flexShrink:0}}
              onClick={e=>e.stopPropagation()}>
              <button onClick={()=>storyIdx>0&&openStory(storyIdx-1)}
                style={{flex:1,padding:"10px",background:"rgba(255,255,255,0.15)",
                  border:"none",borderRadius:10,color:WHITE,fontSize:13,
                  fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
                  cursor:"pointer",opacity:storyIdx>0?1:0.3}}>← PREV</button>
              <button onClick={()=>storyIdx<STORIES.length-1?openStory(storyIdx+1):closeStory()}
                style={{flex:1,padding:"10px",background:"rgba(245,197,24,0.9)",
                  border:"none",borderRadius:10,color:NAVY,fontSize:13,
                  fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,cursor:"pointer"}}>
                {storyIdx<STORIES.length-1?"NEXT →":"CLOSE ✕"}
              </button>
            </div>
          </div>
        )
      })()}

      {/* ══ NEXT MATCH ══ */}
      <div style={{background:`linear-gradient(160deg,${NAVY},#1a3060)`,
        padding:"clamp(14px,4vw,20px) clamp(14px,4vw,18px)",position:"relative",overflow:"hidden"}}>
        <div style={{opacity:0.06,position:"absolute",right:-20,top:-20,pointerEvents:"none"}}>
          <Logo size={180}/>
        </div>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,
          fontSize:10,color:GOLD,letterSpacing:"0.14em",marginBottom:8}}>NEXT MATCH</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
          marginBottom:10,gap:8}}>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,flex:1}}>
            <img src={STARS_LOGO} alt="90 Stars"
              style={{width:"clamp(44px,12vw,58px)",height:"clamp(44px,12vw,58px)",
                objectFit:"contain",borderRadius:"50%",
                background:"rgba(255,255,255,0.08)",padding:2}}/>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(9px,2.5vw,11px)",color:WHITE,textAlign:"center"}}>90 STARS</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:2}}>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(14px,4vw,20px)",color:GOLD}}>VS</span>
            <span style={{fontSize:8,color:"rgba(255,255,255,0.45)",
              fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700}}>WEEK 24</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,flex:1}}>
            <div style={{width:"clamp(44px,12vw,58px)",height:"clamp(44px,12vw,58px)",
              borderRadius:"50%",background:"rgba(255,255,255,0.08)",
              display:"flex",alignItems:"center",justifyContent:"center",
              overflow:"hidden",padding:2}}>
              <img src={GB_LOGO} alt="Golden Birds"
                style={{width:"100%",height:"100%",objectFit:"contain"}}/>
            </div>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(9px,2.5vw,11px)",color:WHITE,textAlign:"center"}}>GOLDEN BIRDS</span>
          </div>
        </div>
        <div style={{fontSize:"clamp(10px,2.5vw,11px)",color:"rgba(255,255,255,0.6)",
          marginBottom:10,display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
          <span>📅 Sat 23 May</span>
          <span>⏰ 13:30</span>
          <span>📍 Falcon Ground</span>
          <span style={{background:GREEN,color:WHITE,padding:"1px 6px",borderRadius:3,
            fontSize:9,fontWeight:800,fontFamily:"'Barlow Condensed',sans-serif"}}>HOME</span>
        </div>
        {countdown ? (
          <div style={{display:"flex",gap:"clamp(6px,2vw,10px)",alignItems:"center"}}>
            <Box val={countdown.d} label="DAYS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.h} label="HRS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.m} label="MINS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.s} label="SECS"/>
            <div style={{marginLeft:"auto"}}>
              <div onClick={()=>setActiveTab&&setActiveTab("calendar")}
                style={{background:GOLD,color:NAVY,borderRadius:8,padding:"8px 12px",
                  fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                  fontSize:11,letterSpacing:"0.06em",textAlign:"center",cursor:"pointer"}}>
                MATCH<br/>CENTER
              </div>
            </div>
          </div>
        ) : (
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
            fontSize:16,color:GOLD,textAlign:"center",padding:"8px 0"}}>
            🕐 KICK OFF TODAY AT 13:30
          </div>
        )}
      </div>

      {/* ══ STORIES (Instagram-style) ══ */}
      <div style={{background:WHITE,padding:"12px 0 8px",
        borderBottom:"1px solid #eee"}}>
        <div style={{display:"flex",gap:12,overflowX:"auto",
          padding:"0 12px",WebkitOverflowScrolling:"touch",
          scrollbarWidth:"none"}}>
          {STORIES.map((s,i)=>{
            const win  = s.result==="W"
            const loss = s.result==="L"
            const seen = false
            return (
              <div key={s.id} onClick={()=>openStory(i)}
                style={{flexShrink:0,display:"flex",flexDirection:"column",
                  alignItems:"center",gap:5,cursor:"pointer",
                  WebkitTapHighlightColor:"transparent"}}>
                {/* Circle */}
                <div style={{
                  width:62,height:62,borderRadius:"50%",padding:3,
                  background:s.result===null
                    ? `linear-gradient(135deg,${GOLD},${GOLD2})`
                    : win
                    ? `linear-gradient(135deg,${GREEN},#16a34a)`
                    : loss
                    ? `linear-gradient(135deg,${RED},#9b1c1c)`
                    : `linear-gradient(135deg,#888,#555)`,
                }}>
                  <div style={{width:"100%",height:"100%",borderRadius:"50%",
                    border:"2px solid white",overflow:"hidden",
                    background:NAVY}}>
                    <img src={s.logo} alt={s.opp}
                      style={{width:"100%",height:"100%",objectFit:"contain",padding:4}}/>
                  </div>
                </div>
                {/* Label */}
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
                  fontSize:"clamp(8px,2vw,10px)",color:NAVY,textAlign:"center",
                  maxWidth:64,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                  {s.opp}
                </div>
                {s.score&&(
                  <div style={{fontSize:9,fontWeight:900,
                    color:win?GREEN:loss?RED:"#888",
                    fontFamily:"'Barlow Condensed',sans-serif",marginTop:-2}}>
                    {s.score} {win?"✓":loss?"✗":"="}
                  </div>
                )}
                {!s.score&&(
                  <div style={{fontSize:9,fontWeight:900,color:GOLD2,
                    fontFamily:"'Barlow Condensed',sans-serif",marginTop:-2}}>
                    NEXT ⚽
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </div>

      {/* ══ QUICK ACTIONS ══ */}
      <div style={{padding:"10px 12px 0",display:"flex",gap:8,overflowX:"auto",
        WebkitOverflowScrolling:"touch"}}>
        {[
          {icon:"🎟",label:"TICKETS",  fn:()=>setActiveTab&&setActiveTab("store")},
          {icon:"👕",label:"SHOP",     fn:()=>setActiveTab&&setActiveTab("store")},
          {icon:"❤️",label:"DONATE",   fn:()=>setShowDonate(true)},
          {icon:"📰",label:"NEWS",     fn:null},
          {icon:"🦡",label:"MEMBERS",  fn:openMembership},
        ].map(item=>(
          <button key={item.label} onClick={item.fn||undefined}
            style={{flexShrink:0,display:"flex",flexDirection:"column",alignItems:"center",
              gap:4,padding:"8px 12px",background:WHITE,border:"1.5px solid #eee",
              borderRadius:12,cursor:item.fn?"pointer":"default",minWidth:60,
              WebkitTapHighlightColor:"transparent",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
            <span style={{fontSize:20}}>{item.icon}</span>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,
              fontSize:9,color:NAVY,letterSpacing:"0.06em"}}>{item.label}</span>
          </button>
        ))}
      </div>

      {/* ══ NEWS FEED ══ */}
      <div style={{padding:"14px 12px 0"}}>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
          fontSize:"clamp(14px,4vw,17px)",color:NAVY,marginBottom:10}}>
          📰 LATEST NEWS
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {displayNews.map((n,i)=>(
            <div key={n.id} style={{background:WHITE,borderRadius:14,overflow:"hidden",
              boxShadow:"0 2px 10px rgba(0,0,0,0.08)"}}>
              {/* Photo */}
              {n.photo&&(
                <div style={{height:"clamp(160px,45vw,200px)",overflow:"hidden",position:"relative"}}>
                  <img src={n.photo} alt={n.title}
                    style={{width:"100%",height:"100%",objectFit:"cover",objectPosition:"center top"}}/>
                  <div style={{position:"absolute",inset:0,
                    background:"linear-gradient(to top,rgba(0,0,0,0.5) 0%,transparent 50%)"}}/>
                  {n.photoCaption&&(
                    <div style={{position:"absolute",bottom:8,left:10,
                      fontSize:10,color:"rgba(255,255,255,0.8)",fontWeight:600}}>
                      📸 {n.photoCaption}
                    </div>
                  )}
                  <div style={{position:"absolute",top:0,left:0,right:0,height:4,
                    background:i===0?GOLD:i%2===0?GREEN:NAVY}}/>
                </div>
              )}
              <div style={{padding:"12px 14px"}}>
                <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}>
                  <span style={{background:NAVY,color:GOLD,fontSize:9,fontWeight:900,
                    padding:"2px 7px",borderRadius:4,
                    fontFamily:"'Barlow Condensed',sans-serif"}}>{n.tag}</span>
                  <span style={{fontSize:11,color:MGRAY}}>{n.date}</span>
                </div>
                <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                  fontSize:"clamp(14px,4vw,17px)",color:NAVY,lineHeight:1.2,marginBottom:6}}>
                  {n.title}
                </div>
                <div style={{fontSize:"clamp(12px,3vw,13px)",color:MGRAY,lineHeight:1.6}}>
                  {n.body}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ══ GALLERY ══ */}
      <div style={{padding:"16px 12px 24px"}}>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
          fontSize:"clamp(14px,4vw,17px)",color:NAVY,marginBottom:10}}>
          📸 GALLERY
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:4}}>
          {[PHOTO_GK,PHOTO_DUO2,PHOTO_NO5,PHOTO_DUO1,PHOTO_NO17,PHOTO_NO6].map((p,i)=>(
            <div key={i} style={{borderRadius:i===0?"14px 4px 4px 4px":
              i===2?"4px 14px 4px 4px":i===3?"4px 4px 4px 14px":
              i===5?"4px 4px 14px 4px":"4px",
              overflow:"hidden",
              height:"clamp(100px,28vw,120px)",background:NAVY}}>
              <img src={p} alt="" style={{width:"100%",height:"100%",
                objectFit:"cover",objectPosition:"center top"}}/>
            </div>
          ))}
        </div>
      </div>

      {/* ══ DONATE BANNER ══ */}
      <div style={{margin:"0 12px 20px"}}>
        <div onClick={()=>setShowDonate(true)}
          style={{background:`linear-gradient(135deg,${RED},#922b21)`,
            borderRadius:14,padding:"14px 16px",cursor:"pointer",
            display:"flex",alignItems:"center",justifyContent:"space-between",
            WebkitTapHighlightColor:"transparent",
            boxShadow:"0 4px 14px rgba(192,57,43,0.3)"}}>
          <div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(14px,4vw,18px)",color:WHITE,lineHeight:1}}>
              ❤️ SUPPORT THE HONEY BADGERS
            </div>
            <div style={{fontSize:"clamp(11px,3vw,13px)",color:"rgba(255,255,255,0.75)",marginTop:4}}>
              Every pula helps the team grow
            </div>
          </div>
          <div style={{background:WHITE,color:RED,borderRadius:8,padding:"8px 14px",
            fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
            fontSize:"clamp(11px,3vw,13px)",flexShrink:0}}>DONATE →</div>
        </div>
      </div>
    </div>
  )
}

export default ForYouScreen
